49	+// reconcileRejections removes only concurrent-ref refusals whose requested hash
50	+// is now present. It never changes the expected-old snapshot or retries writes.
51	+// Each report is checked separately so split pushes still execute later batches
52	+// and cannot hide an unrelated rejection behind a converged ref.
53	+func (p *Pusher) reconcileRejections(ctx context.Context, req *packp.UpdateRequests, report *packp.ReportStatus) *packp.ReportStatus {
54	+	if p.TargetRefsNow == nil || ctx.Err() != nil || (report.UnpackStatus != "" && report.UnpackStatus != "ok") {
55	+		return report
56	+	}
57	+	wanted := make(map[plumbing.ReferenceName]plumbing.Hash)
58	+	for _, cmd := range req.Commands {
59	+		// Absence in an advertisement cannot prove deletion: receive.hideRefs
60	+		// can hide a ref that is still present. Only positive matches qualify.
61	+		if !cmd.New.IsZero() {
62	+			wanted[cmd.Name] = cmd.New
63	+		}
64	+	}
65	+	needsRead := false
66	+	for _, status := range report.CommandStatuses {
67	+		if status.Error() == nil {
68	+			continue
69	+		}
70	+		if canVerifyRefRejection(status.Status) && !wanted[status.ReferenceName].IsZero() {
71	+			needsRead = true
72	+		} else if p.OnRejection == nil {
73	+			// Strict pushes still fail on this refusal. Avoid a full target read
74	+			// that cannot make the report successful.
75	+			return report
76	+		}
77	+	}
78	+	if !needsRead {
79	+		return report
80	+	}
81	+	refs, err := p.TargetRefsNow(ctx)
82	+	if err != nil || ctx.Err() != nil {
83	+		return report
84	+	}
85	+	filtered := &packp.ReportStatus{UnpackStatus: report.UnpackStatus}
86	+	for _, status := range report.CommandStatuses {
87	+		name := status.ReferenceName
88	+		hash := wanted[name]
89	+		if canVerifyRefRejection(status.Status) && !hash.IsZero() && refs[name] == hash {
90	+			p.answer(name, refAnswer{current: true})
91	+			if p.OnAlreadyCurrent != nil {
92	+				p.OnAlreadyCurrent(name, hash)
93	+			}
94	+			continue
95	+		}
96	+		filtered.CommandStatuses = append(filtered.CommandStatuses, status)
97	+	}
98	+	return filtered
99	+}
